async fn computeTIT(publicKey: PublicKey) -> gns_runtime::RuntimeResult<TIT> {
    let hash: Hash = gns_runtime::sha256(publicKey.as_bytes());
    return Ok(TIT { data: hash[0..16].to_vec() });
}

async fn trustLevelFromEpochs(epochs: i64) -> gns_runtime::RuntimeResult<TrustLevel> {
    if epochs == 0 {
        return Ok(TrustLevel::Anonymous);
    }
    if epochs < 10 {
        return Ok(TrustLevel::Verified);
    }
    if epochs < 100 {
        return Ok(TrustLevel::Established);
    }
    return Ok(TrustLevel::Trusted);
}

