async fn computeTrustScore(epochs: i64, peerAttestations: i64, anchorAttestations: i64, secondsSinceActivity: f64, tau0: f64) -> gns_runtime::RuntimeResult<TrustScore> {
    let baseScore: f64 = (1.000000 + (epochs as f64)).log2();
    let peerMultiplier: f64 = 1.000000 + (((peerAttestations as f64) / (CONFIG.parisi_k as f64) as f64)).tanh();
    let anchorMultiplier: f64 = 1.000000 + ((anchorAttestations as f64) / 3.000000).tanh();
    let gamma: f64 = 0.030000;
    let lambda: f64 = 1.000000 - (-secondsSinceActivity / tau0).exp();
    let decayFactor: f64 = (-gamma * lambda * secondsSinceActivity / 86400.000000).exp();
    let total: f64 = baseScore * peerMultiplier * anchorMultiplier * decayFactor;
    return Ok(TrustScore { base_score: baseScore, peer_multiplier: peerMultiplier, anchor_multiplier: anchorMultiplier, decay_factor: decayFactor, total: total });
}

async fn trustDecayAfterDays(initial: f64, days: f64, tau0Days: f64) -> gns_runtime::RuntimeResult<f64> {
    let lambda: f64 = 1.000000 - (-days / tau0Days).exp();
    let gamma: f64 = 0.030000;
    return Ok(initial * (-gamma * lambda * days).exp());
}

