async fn isValidHandle(name: String) -> gns_runtime::RuntimeResult<bool> {
    let clean: String = name.replace("@", "");
    if (clean.len() as i64) < 1 || (clean.len() as i64) > 20 {
        return Ok(false);
    }
    let first = clean.chars().nth(0 as usize).unwrap().to_string();
    if first == "_".to_string() || first.chars().all(|c| c.is_ascii_digit()) {
        return Ok(false);
    }
    return Ok(checkCharsSafely(clean, 0).await?);
}

fn checkCharsSafely(s: String, i: i64) -> std::pin::Pin<Box<dyn std::future::Future<Output = gns_runtime::RuntimeResult<bool>> + Send>> {
    Box::pin(async move {
        if i >= (s.len() as i64) {
            return Ok(true);
        }
        let char = s.chars().nth(i as usize).unwrap().to_string();
        if !char.chars().all(|c| c.is_lowercase()) && !char.chars().all(|c| c.is_ascii_digit()) && char != "_".to_string() {
            return Ok(false);
        }
        return Ok(checkCharsSafely(s, i + 1).await?);
    })
}

