async fn testSignAndVerify() -> gns_runtime::RuntimeResult<()> {
    println!("{:?}", "".to_string());
    println!("{:?}", "── Sign and Verify ──".to_string());
    let me = Keychain::primary()?;

    let message: String = "Hello, TRIP!".to_string();
    let signature = me.sign(message.as_bytes());
    assertTrue((signature.len() as i64) == 64, "Signature is 64 bytes".to_string()).await?;
    let valid = signature.verify(message.as_bytes(), &me.public_key);
    assertTrue(valid, "Signature verifies correctly".to_string()).await?;
    let invalidMsg = signature.verify("Wrong message".to_string().as_bytes(), &me.public_key);
    assertFalse(invalidMsg, "Wrong message fails verification".to_string()).await?;
    let other = Keychain::facet("other")?;

    let invalidKey = signature.verify(message.as_bytes(), &other.public_key);
    assertFalse(invalidKey, "Wrong key fails verification".to_string()).await?;

    Ok(())
}

