async fn testBreadcrumbGenesis() -> gns_runtime::RuntimeResult<()> {
    println!("{:?}", "".to_string());
    println!("{:?}", "── Breadcrumb Genesis ──".to_string());
    let me = Keychain::primary()?;

    let cell: H3Cell = Location::current()?.to_h3(CONFIG.h3_resolution as u8)?;
    let bc: Breadcrumb = gns_runtime::breadcrumb().cell(cell).context(Sensors::current().digest()).previous(None::<&gns_runtime::Breadcrumb>).sign(&me)?;
    assertTrue(bc.index == 0, "Genesis index is 0".to_string()).await?;
    assertTrue(bc.previous_hash == gns_runtime::Hash(Bytes::zeros(32)), "Genesis has no previous".to_string()).await?;
    assertTrue(bc.signature.verify(&bc.to_signable_bytes(), &me.public_key), "Signature is valid".to_string()).await?;

    Ok(())
}

async fn testBreadcrumbChain() -> gns_runtime::RuntimeResult<()> {
    println!("{:?}", "".to_string());
    println!("{:?}", "── Breadcrumb Chain ──".to_string());
    let me = Keychain::primary()?;

    let cell: H3Cell = Location::current()?.to_h3(CONFIG.h3_resolution as u8)?;
    let bc0: Breadcrumb = gns_runtime::breadcrumb().cell(cell).context(Sensors::current().digest()).previous(None::<&gns_runtime::Breadcrumb>).sign(&me)?;
    tokio::time::sleep(std::time::Duration::from_millis(10)).await;
    {
        let bc1: Breadcrumb = gns_runtime::breadcrumb().cell(cell).context(Sensors::current().digest()).previous(Some(&bc0)).sign(&me)?;
        assertTrue(bc1.index == 1, "Second index is 1".to_string()).await?;
        assertTrue(bc1.previous_hash == gns_runtime::sha256(&bc0.to_bytes()), "Previous hash links".to_string()).await?;
        assertTrue(bc1.timestamp > bc0.timestamp, "Timestamp increases".to_string()).await?;
        tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        {
            let bc2: Breadcrumb = gns_runtime::breadcrumb().cell(cell).context(Sensors::current().digest()).previous(Some(&bc1)).sign(&me)?;
            assertTrue(bc2.index == 2, "Third index is 2".to_string()).await?;
            assertTrue(bc2.previous_hash == gns_runtime::sha256(&bc1.to_bytes()), "Chain continues".to_string()).await?;
        }
    }

    Ok(())
}

