async fn testTrustDecay() -> gns_runtime::RuntimeResult<()> {
    println!("{:?}", "".to_string());
    println!("{:?}", "── Trust Decay ──".to_string());
    let initial: f64 = 10.000000;
    let tau0: f64 = 30.000000;
    let t0: f64 = trustDecayAfterDays(initial, 0.000000, tau0).await?;
    assertTrue((t0 - initial).abs() < 0.001000, "No decay at t=0".to_string()).await?;
    let t30: f64 = trustDecayAfterDays(initial, 30.000000, tau0).await?;
    assertTrue(t30 < initial, "Decay at 30 days".to_string()).await?;
    assertTrue(t30 > initial * 0.500000, "Not too much at 30 days".to_string()).await?;
    let t90: f64 = trustDecayAfterDays(initial, 90.000000, tau0).await?;
    assertTrue(t90 < initial * 0.500000, "Significant decay at 90 days".to_string()).await?;
    let t365: f64 = trustDecayAfterDays(initial, 365.000000, tau0).await?;
    assertTrue(t365 < initial * 0.100000, "Heavy decay at 365 days".to_string()).await?;
    println!("{:?}", "".to_string());
    println!("{:?}", "  Decay Timeline (τ₀ = 30 days):".to_string());
    println!("{:?}", "  Days  Trust   Retained".to_string());
    println!("{:?}", "  ────  ─────   ────────".to_string());
    for days in vec![0, 7, 14, 30, 60, 90, 180, 365] {
        let trust: f64 = trustDecayAfterDays(initial, days as f64, tau0).await?;
        let pct: f64 = trust / initial * 100.000000;
        println!("{:?}", format!("  {}	{}	{}%", days, format!("{:.2}", trust), format!("{:.0}", pct)));
    }

    Ok(())
}

