async fn testCompleteLifecycle() -> gns_runtime::RuntimeResult<()> {
    println!("{:?}", "".to_string());
    println!("{:?}", "═══════════════════════════════════════════════".to_string());
    println!("{:?}", "    TRIP Identity Lifecycle Demo".to_string());
    println!("{:?}", "═══════════════════════════════════════════════".to_string());
    println!("{:?}", "".to_string());
    println!("{:?}", "1. Generating identities...".to_string());
    let human = Keychain::primary()?;

    let drone = Keychain::facet("drone_42")?;

    let humanTIT: TIT = TIT::from_public_key(human.public_key.as_bytes());
    let droneTIT: TIT = TIT::from_public_key(drone.public_key.as_bytes());
    println!("{:?}", format!("   Human TIT: {}", hex::encode(&humanTIT.data)));
    println!("{:?}", format!("   Drone TIT: {}", hex::encode(&droneTIT.data)));
    println!("{:?}", format!("   Human Stellar: {}", human.stellar_address()));
    println!("{:?}", "".to_string());
    println!("{:?}", "2. Handles (earned through trajectory)...".to_string());
    println!("{:?}", "   Human: @alice".to_string());
    println!("{:?}", "   Drone: @drone_42".to_string());
    println!("{:?}", "".to_string());
    println!("{:?}", "3. Collecting breadcrumbs (MOVING pattern)...".to_string());
    let cell: H3Cell = Location::current()?.to_h3(CONFIG.h3_resolution as u8)?;
    let bc0: Breadcrumb = gns_runtime::breadcrumb().cell(cell).context(Sensors::current().digest()).previous(None::<&gns_runtime::Breadcrumb>).sign(&human)?;
    println!("{:?}", format!("   bc[0]: Home - index {}", bc0.index));
    println!("{:?}", "".to_string());
    println!("{:?}", "4. Trust progression (from epochs)...".to_string());
    for epochs in vec![0, 1, 5, 10, 50, 100] {
        let level: TrustLevel = trustLevelFromEpochs(epochs).await?;
        println!("{:?}", format!("   {} epochs → {}", epochs, level));
    }
    println!("{:?}", "".to_string());
    println!("{:?}", format!("5. Trust score (Parisi k={})...", CONFIG.parisi_k));
    let score: TrustScore = computeTrustScore(10, CONFIG.parisi_k, 2, 3600.000000, CONFIG.tau0_human as f64).await?;
    println!("{:?}", format!("   Base: {}", format!("{:.2}", score.base_score)));
    println!("{:?}", format!("   Peer multiplier: {}", format!("{:.2}", score.peer_multiplier)));
    println!("{:?}", format!("   Decay: {}", format!("{:.4}", score.decay_factor)));
    println!("{:?}", format!("   Total: {}", format!("{:.2}", score.total)));
    println!("{:?}", "".to_string());
    println!("{:?}", "═══════════════════════════════════════════════".to_string());
    println!("{:?}", "  TRIP: Identity is MOVEMENT".to_string());
    println!("{:?}", "  The trajectory IS the identity.".to_string());
    println!("{:?}", "═══════════════════════════════════════════════".to_string());
    assertTrue(true, "Complete lifecycle executed".to_string()).await?;

    Ok(())
}


